/* PATCH 1.0.1 — экспорт в Excel */
function exportCalendarToExcel() {
    var month = state.calendar ? state.calendar.month : new Date().getMonth() + 1;
    var year = state.calendar ? state.calendar.year : new Date().getFullYear();
    var params = new URLSearchParams();
    params.set('month', month);
    params.set('year', year);
    var deptFilter = document.getElementById('calDeptFilter');
    if (deptFilter && deptFilter.value) params.set('department', deptFilter.value);
    var teamFilter = document.getElementById('calTeamFilter');
    if (teamFilter && teamFilter.value) params.set('team', teamFilter.value);
    var empFilter = document.getElementById('calEmployeeFilter');
    if (empFilter && empFilter.value) params.set('employee', empFilter.value);
    notify('📊 Генерируем Excel...', 'info');
    window.open('/api/tracker/calendar/export?' + params.toString(), '_blank');
}
function toggleExportMenu(force) {
    var drop = document.getElementById('exportMenuDrop');
    if (!drop) return;
    var show = (force === true) || drop.style.display === 'none';
    drop.style.display = show ? 'block' : 'none';
}
function runExportForm(form) {
    toggleExportMenu(false);
    if (form === 'calendar') exportCalendarToExcel();
    else if (form === 'debtors') exportDebtorsToExcel();
}
function exportDebtorsToExcel() {
    var d = new Date();
    var iso = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    var params = new URLSearchParams();
    params.set('date', iso);
    var deptFilter = document.getElementById('calDeptFilter');
    if (deptFilter && deptFilter.value) params.set('department', deptFilter.value);
    var teamFilter = document.getElementById('calTeamFilter');
    if (teamFilter && teamFilter.value) params.set('team', teamFilter.value);
    notify('⚠️ Считаем, кто не заполнил отчёт...', 'info');
    window.open('/api/tracker/export/debtors?' + params.toString(), '_blank');
}
(function(){
    if (window.__trkExportMenuBound) return;
    window.__trkExportMenuBound = true;
    document.addEventListener('click', function(e) {
        var t = e.target;
        if (!t || !t.closest) return;
        if (t.closest('#exportMenuBtn')) {
            e.preventDefault();
            e.stopPropagation();
            toggleExportMenu();
            return;
        }
        var item = t.closest('.export-menu-item');
        if (item) { runExportForm(item.getAttribute('data-form')); return; }
        var drop = document.getElementById('exportMenuDrop');
        if (drop && drop.style.display !== 'none' && !t.closest('.export-menu-wrap')) {
            drop.style.display = 'none';
        }
    }, true);
})();

/* ============================================================
   PATCH 1.0.1 — единый перехватчик /api/tracker/log/save
   Guard: __trkLogSaveUnifiedV1101 (старый __trkLogSaveUnifiedV1035 отключён
   через prepend-guard, поэтому старый блок B3 остаётся в файле, но не запускается)
   ============================================================ */
(function(){
'use strict';
if (window.__trkLogSaveUnifiedV1101) return;
window.__trkLogSaveUnifiedV1101 = true;

var _native = window.fetch;
if (typeof _native !== 'function') return;

function _csrf(){ try { return window.REESTR_CSRF || ''; } catch(e){ return ''; } }
function _collectExtra(){
    var box = document.getElementById('logExtraDataList');
    if (!box) return [];
    var out = [];
    box.querySelectorAll('.task-link-row input[type="text"]').forEach(function(inp){
        var v = (inp.value || '').trim();
        if (v) out.push(v);
    });
    return out;
}
function _collectOrders(){
    var box = document.getElementById('logOrdersList');
    if (!box) return [];
    var out = [];
    box.querySelectorAll('.task-link-row').forEach(function(row){
        var d = row.querySelector('.task-order-desc');
        var v = row.querySelector('.task-order-val');
        var vv = v ? (v.value || '').trim() : '';
        if (vv) out.push({ description: d ? (d.value || '').trim() : '', value: vv });
    });
    return out;
}
function _collectLinks(){
    var box = document.getElementById('logLinksList');
    if (!box) return [];
    var out = [];
    box.querySelectorAll('.task-link-row').forEach(function(row){
        var d = row.querySelector('.task-link-desc');
        var u = row.querySelector('.task-link-url');
        var uu = u ? (u.value || '').trim() : '';
        if (uu) out.push({ description: d ? (d.value || '').trim() : '', url: uu });
    });
    return out;
}
function _enrichBody(body){
    var extra = _collectExtra();
    var orders = _collectOrders();
    var links = _collectLinks();
    if (extra.length) body.extra_data = extra;
    if (orders.length) body.orders = orders;
    if (links.length) body.links = links;
    var ta = document.getElementById('log_comment');
    if (ta) {
        if (!body.comment) body.comment = (ta.value || '').trim();
        if (!body.description) body.description = (ta.value || '').trim();
    }
    body.merge_into_task = 1;
    return body;
}
function _getOverflowModal(){
    var m = document.getElementById('trkOverflowModal');
    if (m) return m;
    m = document.createElement('div');
    m.id = 'trkOverflowModal';
    m.className = 'modal trk-overflow-modal';
    m.style.setProperty('z-index', '9000', 'important');
    m.innerHTML = '<div class="modal-content ov-modal">'
        + '<div class="ov-head"><span class="ov-icon">⚠</span>'
        + '<div class="ov-title-block"><div class="ov-title">Превышение 8 часов за день</div>'
        + '<div class="ov-sub" id="trkOvSub"></div></div></div>'
        + '<div class="ov-numbers" id="trkOvNumbers"></div>'
        + '<div class="ov-note"><b>Принять</b> — сохранить как введено. <b>Распределить</b> — поделить 8 часов между всеми задачами дня поровну.</div>'
        + '<label class="ov-remember"><input type="checkbox" id="trkOvRemember"><span>Запомнить выбор на эту сессию</span></label>'
        + '<div class="ov-actions"><button type="button" class="btn btn-secondary" data-ov="cancel">Закрыть</button>'
        + '<button type="button" class="btn btn-secondary" data-ov="distribute">Распределить</button>'
        + '<button type="button" class="btn btn-primary" data-ov="accept">Принять</button></div>'
        + '</div>';
    document.body.appendChild(m);
    return m;
}
function _showOverflow(info){
    return new Promise(function(resolve){
        var SK = 'tracker_overflow_choice_v2';
        var stored = '';
        try { stored = sessionStorage.getItem(SK) || ''; } catch(e){}
        if (stored === 'accept' || stored === 'distribute') { resolve(stored); return; }
        var m = _getOverflowModal();
        var sub = m.querySelector('#trkOvSub');
        var nums = m.querySelector('#trkOvNumbers');
        var remember = m.querySelector('#trkOvRemember');
        if (sub) sub.textContent = (info.employee_name || 'Сотрудник') + ' · ' + (info.date || '');
        var over = (info.total || 0) - 8;
        function fh(x){ var v = Math.round((x || 0) * 100) / 100; return (v === Math.floor(v) ? v : v.toFixed(2).replace(/0+$/, '').replace(/\.$/, '')) + ' ч'; }
        if (nums) nums.innerHTML = '<div class="ov-num-row"><span class="ov-num-label">Уже за день</span><span class="ov-num-val">' + fh(info.sum_existing) + '</span></div>'
            + '<div class="ov-num-row"><span class="ov-num-label">Новая отметка</span><span class="ov-num-val">' + fh(info.new_hours) + '</span></div>'
            + '<div class="ov-num-sep"></div>'
            + '<div class="ov-num-row ov-num-total"><span class="ov-num-label">Итого будет</span><span class="ov-num-val ov-danger">' + fh(info.total) + '</span></div>'
            + '<div class="ov-num-row ov-num-warn"><span class="ov-num-label">Переработка</span><span class="ov-num-val">' + fh(over) + '</span></div>';
        m.classList.add('active');
        var resolved = false;
        function finish(choice){
            if (resolved) return;
            resolved = true;
            m.classList.remove('active');
            m.removeEventListener('click', onClick);
            if (choice !== 'cancel' && remember && remember.checked) {
                try { sessionStorage.setItem(SK, choice); } catch(e){}
            }
            resolve(choice);
        }
        function onClick(e){
            if (e.target === m) { finish('cancel'); return; }
            var b = e.target.closest && e.target.closest('[data-ov]');
            if (!b) return;
            finish(b.getAttribute('data-ov'));
        }
        m.addEventListener('click', onClick);
    });
}
function _onSuccess(body, d){
    try {
        if (body.employee_id && body.task_id) {
            var st = window.__trkState || {};
            var task = (st.tasks || []).find(function(t){ return t.id === body.task_id; });
            if (task) {
                var cur = Array.isArray(task.assignees) ? task.assignees.slice() : [];
                if (cur.indexOf(body.employee_id) === -1) {
                    cur.push(body.employee_id);
                    var payload = { id: task.id, name: task.name || '', icon: task.icon || '📋', description: task.description || '', status: task.status || 'active', start_date: task.start_date || '', deadline: task.deadline || '', completed_at: task.completed_at || '', folder: task.folder || '', order_ref: task.order_ref || '', tags: (task.tags || []).slice(), assignees: cur, department_ids: (task.department_ids || []).slice(), is_urgent: !!task.is_urgent, links: (task.links || []).slice(), orders: (task.orders || []).slice() };
                    var hdrs = {'Content-Type': 'application/json'};
                    if (_csrf()) hdrs['X-CSRF-Token'] = _csrf();
                    _native('/api/tracker/task/save', { method: 'POST', headers: hdrs, credentials: 'same-origin', body: JSON.stringify(payload) }).catch(function(){});
                    task.assignees = cur;
                }
            }
        }
    } catch (e) { console.error('[unified-log-save] auto-assign', e); }
    ['logModal', 'dayModal', 'taskModal'].forEach(function(id){
        var m = document.getElementById(id);
        if (m && m.classList.contains('active')) m.classList.remove('active');
    });
    var _refresh = (typeof window.__trkRefreshAll === 'function') ? window.__trkRefreshAll : (typeof window.__trkRenderCalendar === 'function' ? window.__trkRenderCalendar : null);
    if (_refresh) { setTimeout(function(){ Promise.resolve(_refresh()); }, 80); }
}
window.fetch = function(url, opts){
    var isLogSave = (typeof url === 'string' && url.indexOf('/api/tracker/log/save') !== -1);
    var isPost = opts && (opts.method || 'GET').toUpperCase() === 'POST';
    if (!isLogSave || !isPost) return _native.apply(this, arguments);
    var body = {};
    try { body = JSON.parse(opts.body || '{}'); } catch (e) {}
    body = _enrichBody(body);
    var self = this;
    var newOpts = Object.assign({}, opts, { body: JSON.stringify(body) });
    return _native.call(self, url, newOpts).then(function(r){
        if (r.status === 409) {
            return r.clone().json().then(function(d){
                if (d && d.error === 'daily_overflow') {
                    var info = { sum_existing: d.sum_existing || 0, new_hours: d.new_hours || 0, total: d.total || 0, employee_name: d.employee_name || '', date: d.date || body.date || '' };
                    if (!info.employee_name) { var st = window.__trkState || {}; var emp = (st.employees || []).find(function(e){ return e.id === body.employee_id; }); if (emp) info.employee_name = emp.name; }
                    if (!info.date) info.date = body.date || '';
                    return _showOverflow(info).then(function(choice){
