function refresh() {
    Promise.all([
        fetch('/api/notifications', {credentials: 'same-origin'}).then(function(r) { return r.json(); }).catch(function() { return null; }),
        fetch('/api/plugins/reminders/me', {credentials: 'same-origin'}).then(function(r) { return r.json(); }).catch(function() { return null; })
    ]).then(function(results) {
        var notif = results[0] || {};
        var rem = results[1] || {};
        var items = (notif.items || []).slice();
        var remItems = (rem.success && rem.items) ? rem.items : [];
        remItems.forEach(function(it) {
            items.unshift({
                id: 'rem_' + it.task_id + '_' + it.kind,
                kind: 'reminder', task_id: it.task_id,
                message: it.task_name, status: 'info',
                read_at: '', ts: '', _reminder: it
            });
        });
        var cnt = document.getElementById('trkBellCount');
        var total = (notif.unread || 0) + remItems.length;
        if (cnt) {
            if (total > 0) { cnt.style.display = ''; cnt.textContent = total > 99 ? '99+' : String(total); }
            else cnt.style.display = 'none';
        }
        var drop = document.getElementById('trkBellDrop');
        if (drop && drop.style.display !== 'none') {
            _renderList(items);
        } else {
            _ensureDrop();
            _renderList(items);
            var dd = document.getElementById('trkBellDrop');
            if (dd) dd.style.display = 'none';
        }
    }).catch(function(){});
}

